&lt;/div&gt;
Ces objets regroupent les gantelets, les gants et tous les objets port&#233;s aux mains.&lt;br /&gt;&lt;br /&gt;Tout le monde peut utiliser un objet merveilleux port&#233; aux mains &#224; moins que le contraire ne soit indiqu&#233; dans sa description. Ces objets sont habituellement activ&#233;s par usage ou par un mot de commande mais il y a parfois des diff&#233;rences en fonction des objets.&lt;br /&gt;&lt;br /&gt;Tous les objets merveilleux d&#233;crits ci-dessous p&#232;sent entre 0 g et 1 kg, sauf certains &lt;i&gt;Gantelets&lt;/i&gt; qui p&#232;sent 2,5 kg.&lt;br /&gt;&lt;br /&gt;&lt;script type=&quot;text/javascript&quot;&gt;
$(filtrable_init);

function filtrable_init() {
    // Find all tables with class filtrable and make them filtrable
    $(&quot;table.filtrable&quot;).each(makeFiltrable);
}

function makeFiltrable() {
    var table = $(this);
    var rows = table.find(&quot;tr&quot;);
    if (rows.length &lt; 2) {
        return;
    }
    var firstRow = rows.first();
    var cells = firstRow.children(&quot;td,th&quot;);
    table.get()[0].filters = [];
    cells.each(function (idx) {
        var contents = $(this).html;
        var filterLogo = $(&quot;&lt;img height=&#39;12px&#39; /&gt;&quot;);
        filterLogo.attr(&#39;src&#39;, &#39;/wiki/public/Upload/Battlemaps/Boutons/filter.png&#39;);
        filterLogo.attr(&#39;title&#39;, &#39;Cliquez ici pour filtrer les donn&#233;es&#39;);
        filterLogo.css(&#39;padding&#39;, &#39;0&#39;);
        filterLogo.click(doFilter(idx,filterLogo,table));
        $(this).prepend(filterLogo);
        table.get()[0].filters.push(null);
    });
}
function doFilter(nCol, logo, table) {
    return function () {
        var filter = prompt(&quot;Entrez le filtre &#224; appliquer.\nLaisser le cadre vide pour tout afficher; utilisez &#39;mot1|mot2&#39; pour un choix multiple.&quot;, &quot;&quot;).trim();
        if (filter == &quot;&quot;) {
            table.get()[0].filters[nCol] = null;
            logo.css(&quot;background-color&quot;, &quot;&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : aucun - cliquez pour changer le filtre&quot;);
        } else {
            table.get()[0].filters[nCol] = new RegExp(filter.trim(),&quot;i&quot;);
            logo.css(&quot;background-color&quot;, &quot;yellow&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : &quot; + (filter == &quot;&quot; ? &quot;aucun&quot; : filter)
                + &quot; - cliquez pour changer le filtre&quot;);
        }
        applyFilter(table);
    };
}
function applyFilter(table) {
    var rows = table.find(&quot;tr&quot;).filter(function (idx) {
        return idx &gt; 0 &amp;&amp; $(this).children(&quot;th&quot;).length == 0;
    });
    rows.each(function () {
        var keep = mustKeep(this,table.get()[0].filters);
        $(this).css(&quot;display&quot;, keep ? &quot;table-row&quot; : &quot;none&quot;);
    });
}
function mustKeep(row,filters) {
    var cells = $(row).children(&quot;td&quot;);
    var nCols = filters.length;
    var keep = true;
    var iCol = 0;
    while (keep &amp;&amp; iCol &lt; nCols) {
        keep = filters[iCol] === null ||
            cells.eq(iCol).html().match(filters[iCol]) != null;
        iCol++;
    }
    return keep;
}
&lt;/script&gt;
&lt;table CLASS=&quot;tablo centre autoalt toutgauche filtrable&quot;&gt;&lt;caption&gt;Objets merveilleux port&#233;s sur les mains&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;22%&quot;&gt;Objet&lt;/td&gt;&lt;td WIDTH= &quot;3%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;65%&quot;&gt;Capacit&#233;s&lt;/td&gt;&lt;td WIDTH=&quot;10%&quot;&gt;Prix de vente&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-De-Soutien.html&quot; title=&quot;Gants de soutien&quot;&gt;Gants de soutien&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peuvent convoquer une main spectrale capable d’&lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales.html#AIDERQQN&quot; title=&quot;Actions sp&#233;ciales&quot;&gt;aider quelqu’un&lt;/a&gt; (une fois) pendant 1 minute &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;180 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Griffes-De-Lours-Polaire.html&quot; title=&quot;Griffes de l’ours polaire&quot;&gt;Griffes de l’ours polaire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionnent comme des gantelets clout&#233;s. Conf&#232;rent un bonus de comp&#233;tence de +5 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; quand le porteur se d&#233;place avec ses deux mains. Trois fois par jour, peuvent conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pattes-Daraign&#233;e.html&quot; title=&quot;Pattes d&amp;#39;araign&#233;e&quot;&gt;pattes d’araign&#233;e&lt;/a&gt;&lt;/i&gt; pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;1 300 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-Luisants.html&quot; title=&quot;Gants luisants&quot;&gt;Gants luisants&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peuvent &#233;clairer une zone de 18 m de rayon autour d’une surface pendant 1 journ&#233;e, &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;2 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mitaines-De-Reconnaissance.html&quot; title=&quot;Mitaines de reconnaissance&quot;&gt;Mitaines de reconnaissance&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu’&#224; 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par jour, permettent d’entendre les sons &#224; travers des mat&#233;riaux compacts de 1,50 m d’&#233;paisseur maximum.&lt;/td&gt;&lt;td&gt;2 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-Dapprenti-Prestidigitateur.html&quot; title=&quot;Gants d’apprenti prestidigitateur&quot;&gt;Gants d’apprenti prestidigitateur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permettent de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Manipulation-&#192;-Distance.html&quot; title=&quot;Manipulation &#224; distance&quot;&gt;manipulation &#224; distance&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Prestidigitation.html&quot; title=&quot;Prestidigitation&quot;&gt;prestidigitation&lt;/a&gt;&lt;/i&gt; &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;2 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-Du-D&#233;fi.html&quot; title=&quot;Gants du d&#233;fi&quot;&gt;Gants du d&#233;fi&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peuvent &#234;tre lanc&#233;s pour d&#233;fier une cr&#233;ature, conf&#233;rant un bonus de moral de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDATTAQUE&quot; title=&quot;Valeurs de combat&quot;&gt;jets d’attaque&lt;/a&gt; contre elle et cette derni&#232;re subit un malus &#233;quivalent contre le porteur. Ces bonus durent 1 minute sauf si une autre cr&#233;ature que le porteur attaque la cible du d&#233;fi.&lt;/td&gt;&lt;td&gt;2 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-Descamotage.html&quot; title=&quot;Gants d’escamotage&quot;&gt;Gants d’escamotage&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de +5 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;2 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-Des-Doigts-Rapides.html&quot; title=&quot;Gants des doigts rapides&quot;&gt;Gants des doigts rapides&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet &#224; un porteur avec au moins 1 rang en &lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt; d’en effectuer des tests par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt; avec un malus de -10 (au lieu de -20).&lt;/td&gt;&lt;td&gt;2 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-Du-Gu&#233;risseur.html&quot; title=&quot;Gants du gu&#233;risseur&quot;&gt;Gants du gu&#233;risseur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;Premiers secours&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;2 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gantelet-De-Lh&#233;riti&#232;re.html&quot; title=&quot;Gantelet de l&amp;#39;H&#233;riti&#232;re&quot;&gt;Gantelet de l&#39;H&#233;riti&#232;re&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, peut conf&#233;rer un bonus d&#39;alt&#233;ration de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d&#39;attaque&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt; d&#39;une arme que le porteur tient pendant 1 minute. Un suivant d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Iom&#233;dae-(Technique).html&quot; title=&quot;Iom&#233;dae&quot;&gt;Iom&#233;dae&lt;/a&gt; peut conf&#233;rer la propri&#233;t&#233; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Tueuse.html&quot; title=&quot;tueuse (propri&#233;t&#233;)&quot;&gt;tueuse&lt;/a&gt; d&#39;ext&#233;rieur Mauvais&lt;/i&gt; &#224; une arme qu&#39;il tient pendant 1 minute, faire briller une surface solide &#224; volont&#233;, et utiliser cet objet comme &lt;a class=&quot;pagelink&quot; href=&quot;Symbole-Sacr&#233;-(Objet).html&quot; title=&quot;Symbole sacr&#233;&quot;&gt;symbole sacr&#233;&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;2 700 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-Ding&#233;nieur.html&quot; title=&quot;Gants d’ing&#233;nieur&quot;&gt;Gants d’ing&#233;nieur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de +5 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; pour r&#233;parer les m&#233;canismes ou comprendre leur fonctionnement. Une fois par jour, le porteur peut analyser les m&#233;caniques d’un objet d’un simple contact.&lt;/td&gt;&lt;td&gt;3 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gantelets-De-Manœuvre-Offensive.html&quot; title=&quot;Gantelets de manœuvre offensive&quot;&gt;Gantelets de manœuvre offensive&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html&quot; title=&quot;Les manœuvres offensives&quot;&gt;manœuvres offensives&lt;/a&gt; d’une certaine manœuvre, choisie &#224; la fabrication.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gantelets-De-Poigne-De-Fer.html&quot; title=&quot;Gantelets de poigne de fer&quot;&gt;Gantelets de poigne de fer&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;R&#233;duit de 2 le malus impos&#233; par le maniement d&#39;une arme improvis&#233;e ou de taille inadapt&#233;e.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-Antiprojectiles.html&quot; title=&quot;Gants antiprojectiles&quot;&gt;Gants antiprojectiles&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Deux fois par jour, permettent d’utiliser &lt;a class=&quot;pagelink&quot; href=&quot;Parade-De-Projectiles.html&quot; title=&quot;Parade de projectiles&quot;&gt;Parade de projectiles&lt;/a&gt;. Rendent les mains du porteur invisibles.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-De-D&#233;samor&#231;age-Des-Pi&#232;ges.html&quot; title=&quot;Gants de d&#233;samor&#231;age des pi&#232;ges&quot;&gt;Gants de d&#233;samor&#231;age des pi&#232;ges&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Sabotage.html&quot; title=&quot;Sabotage&quot;&gt;Sabotage&lt;/a&gt; pour d&#233;samorcer les pi&#232;ges et un bonus de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt; contre ceux-ci.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-De-Vision-Spectrale.html&quot; title=&quot;Gants de vision spectrale&quot;&gt;Gants de vision spectrale&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permettent de voir les mort-vivants dans un rayon de 18 m pendant 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;. Ce pouvoir occulte la vision qu’&#224; le porteur des autres cr&#233;atures. Permettent de d&#233;penser une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html#CANALISATIONDENERGIE&quot; title=&quot;Le pr&#234;tre&quot;&gt;canalisation d’&#233;nergie&lt;/a&gt; positive pour effectuer une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquesdecontact.html&quot; title=&quot;contact&quot;&gt;attaque de contact&lt;/a&gt; &#224; distance infligeant des d12 au lieu de d6. &lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-De-Premiers-Secours.html&quot; title=&quot;Gants de premiers secours&quot;&gt;Gants de premiers secours&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Contiennent 10 charges qui peuvent &#234;tre d&#233;pens&#233;es pour lancer divers sorts d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Guerison.html&quot; title=&quot;Gu&#233;rison&quot;&gt;invocation (gu&#233;rison)&lt;/a&gt;, ne se recharge pas.&lt;/td&gt;&lt;td&gt;4 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-De-Frappe-Magique.html&quot; title=&quot;Gants de frappe magique&quot;&gt;Gants de frappe magique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Si le porteur poss&#232;de le don &lt;a class=&quot;pagelink&quot; href=&quot;Frappe-Magique.html&quot; title=&quot;Frappe magique&quot;&gt;Frappe magique&lt;/a&gt;, une cr&#233;ature qu’il &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales.html#AIDERQQN&quot; title=&quot;Actions sp&#233;ciales&quot;&gt;aide&lt;/a&gt; &#224; r&#233;ussir un jet d’attaque ajoute le bonus aux d&#233;g&#226;ts de ce don &#224; son attaque, il ajoute ce m&#234;me bonus &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; d’une cr&#233;ature qu’il &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Sp&#233;ciales.html#AIDERQQN&quot; title=&quot;Actions sp&#233;ciales&quot;&gt;aide&lt;/a&gt; &#224; am&#233;liorer sa &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;. Lorsque le porteur r&#233;ussit une &lt;a class=&quot;pagelink&quot; href=&quot;Frappe-Magique.html&quot; title=&quot;Frappe magique&quot;&gt;Frappe magique&lt;/a&gt;, les ennemis adjacents &#224; sa cible re&#231;oivent des d&#233;g&#226;ts &#233;gaux au bonus de d&#233;g&#226;ts de la &lt;a class=&quot;pagelink&quot; href=&quot;Frappe-Magique.html&quot; title=&quot;Frappe magique&quot;&gt;Frappe magique&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-Dextraction.html&quot; title=&quot;Gants d&amp;#39;extraction&quot;&gt;Gants d&#39;extraction&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, apr&#232;s un &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Desarmement.html&quot; title=&quot;d&#233;sarmement&quot;&gt;d&#233;sarmement&lt;/a&gt; r&#233;ussit, permet de voler une propri&#233;t&#233; sp&#233;ciale de l&#39;arme d&#233;sarm&#233;e pour en faire profiter les attaques &#224; mains nues du porteur pendant 1d4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-Empoisonn&#233;s.html&quot; title=&quot;Gants empoisonn&#233;s&quot;&gt;Gants empoisonn&#233;s&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peuvent contenir une dose de poison/potion/&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#INFUSION&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;infusion&lt;/a&gt;. Une fois par jour pour chaque gant, le porteur peut injecter la dose contenue par une attaque &#224; mains nues ou naturelle au contact.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-De-Puissance-Squelettique.html&quot; title=&quot;Gants de puissance squelettique&quot;&gt;Gants de puissance squelettique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Blessure-Mod&#233;r&#233;e.html&quot; title=&quot;Blessure mod&#233;r&#233;e&quot;&gt;blessure mod&#233;r&#233;e&lt;/a&gt;&lt;/i&gt; (ou &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Soins-Mod&#233;r&#233;s.html&quot; title=&quot;Soins mod&#233;r&#233;s&quot;&gt;soins mod&#233;r&#233;s&lt;/a&gt;&lt;/i&gt; sur soi-m&#234;me uniquement) et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Main-Spectrale.html&quot; title=&quot;Main spectrale&quot;&gt;main spectrale&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;5 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gantelets-Briseurs-Dos.html&quot; title=&quot;Gantelets briseurs d&amp;#39;os&quot;&gt;Gantelets briseurs d’os&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, sur une attaque au corps &#224; corps r&#233;ussie, peut r&#233;duire la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt;, la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; ou la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; de la cible de 6 points (sans passer en dessous de 1).&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-Magn&#233;tiques.html&quot; title=&quot;Gants magn&#233;tiques&quot;&gt;Gants magn&#233;tiques&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, permettent de tenter une manœuvre de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#DESARMEMENT&quot; title=&quot;Les manœuvres offensives&quot;&gt;d&#233;sarmement&lt;/a&gt; sur une cible &#224; 9 m ou moins, rapprochant l’objet d&#233;sarm&#233; du porteur.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-De-Nage-Et-Descalade.html&quot; title=&quot;Gants de nage et d&amp;#39;escalade&quot;&gt;Gants de nage et d’escalade&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de comp&#233;tence de +5 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;6 250 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-De-Marquage.html&quot; title=&quot;Gants de marquage&quot;&gt;Gants de marquage&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Quand le porteur manie une arme perforante ou tranchante et utilise &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Finesse.html&quot; title=&quot;Attaque en finesse&quot;&gt;Attaque en finesse&lt;/a&gt;, sur un critique confirm&#233;, il peut &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Secou&#233;.html&quot; title=&quot;secou&#233;&quot;&gt;secouer&lt;/a&gt; la cible et conf&#233;rer un bonus de moral de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt; au corps &#224; corps de ses alli&#233;s contre elle pendant 1 minute au lieu d’infliger des d&#233;g&#226;ts suppl&#233;mentaires.&lt;/td&gt;&lt;td&gt;7 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-Dadversaire-Des-B&#234;tes.html&quot; title=&quot;Gants d&amp;#39;adversaire des b&#234;tes&quot;&gt;Gants d’adversaire des b&#234;tes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus d’alt&#233;ration de +1 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Lutte.html&quot; title=&quot;lutte&quot;&gt;lutte&lt;/a&gt;. Quand le porteur agrippe une cr&#233;ature d’un type choisi &#224; la fabrication en situation de lutte, le bonus d’alt&#233;ration conf&#233;r&#233; passe &#224; +2 et il inflige 2d6 points de d&#233;g&#226;ts &lt;a class=&quot;pagelink&quot; href=&quot;Blessures-Et-Mort.html#NONLETAL&quot; title=&quot;Blessures et mort&quot;&gt;non l&#233;taux&lt;/a&gt; suppl&#233;mentaires s’il d&#233;cide d’infliger des d&#233;g&#226;ts apr&#232;s avoir r&#233;ussi un test de lutte.&lt;/td&gt;&lt;td&gt;7 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-Elfiques.html&quot; title=&quot;Gants elfiques&quot;&gt;Gants elfiques&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de comp&#233;tence de +5 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; pour lancer des sorts &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts.html#INCANTATIONSURLADEFENSIVE&quot; title=&quot;Lancer des sorts&quot;&gt;sur la d&#233;fensive&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;7 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gantelet-Du-Cobra-De-Fer.html&quot; title=&quot;Gantelet du cobra de fer&quot;&gt;Gantelet du cobra de fer&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, peuvent se transformer en &lt;a class=&quot;pagelink&quot; href=&quot;Cobra-De-Fer.html&quot; title=&quot;Cobra de fer&quot;&gt;cobra de fer&lt;/a&gt; servant fid&#232;lement le porteur pendant 1 heure maximum.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gantelets-De-Neutralisation-Des-M&#233;tamorphes.html&quot; title=&quot;Gantelets de neutralisation des m&#233;tamorphes&quot;&gt;Gantelets de neutralisation des m&#233;tamorphes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de moral de +2 aux jets d’attaque &#224; mains nues et naturelle, ainsi qu’aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html&quot; title=&quot;Les manœuvres offensives&quot;&gt;manœuvres offensives&lt;/a&gt; contre les cr&#233;atures capables de changer de forme &#224; volont&#233;. En situation de lutte, endigue les pouvoirs de m&#233;tamorphose et peut forcer &#224; d&#233;voiler la vraie forme.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-De-D&#233;combres.html&quot; title=&quot;Gants de d&#233;combres&quot;&gt;Gants de d&#233;combres&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Vingt fois par jour, peut cr&#233;er une case de &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;placement-Et-Position#Terraindifficile.html&quot; title=&quot;terrain difficile&quot;&gt;terrain difficile&lt;/a&gt; &#224; partir de pierre ou de terre.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-De-Magus.html&quot; title=&quot;Gants de magus&quot;&gt;Gants de magus&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, permettent de changer la port&#233;e d’un sort &#224; distance en sort au &#171; contact &#187; &#233;ligible pour la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#FRAPPEMAGIQUE&quot; title=&quot;Le magus&quot;&gt;frappe magique&lt;/a&gt; du &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html&quot; title=&quot;Le magus&quot;&gt;magus&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-D&#233;liquescents.html&quot; title=&quot;Gants d&#233;liquescents&quot;&gt;Gants d&#233;liquescents&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Les attaques &#224; mains nues infligent 1d6 points de d&#233;g&#226;ts d’acide. Conf&#232;rent la propri&#233;t&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Corrosive.html&quot; title=&quot;corrosive (propri&#233;t&#233;)&quot;&gt;corrosive&lt;/a&gt; aux armes mani&#233;es. Immunise contre le pouvoir d’acide des &lt;a class=&quot;pagelink&quot; href=&quot;Type-Vase.html&quot; title=&quot;Vase&quot;&gt;vases&lt;/a&gt; et contre la division de celles-ci sous les coups des attaques &#224; mains nues et naturelles.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-Ensanglant&#233;s.html&quot; title=&quot;Gants ensanglant&#233;s&quot;&gt;Gants ensanglant&#233;s&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Quand ils sont plong&#233;s dans le sang d’une cr&#233;ature tout juste morte, conf&#232;rent un bonus d’intuition de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt;] et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt; contre les cr&#233;atures du m&#234;me type (ou sous-type pour les humano&#239;des ou les ext&#233;rieurs) pendant 1 heure (Le bonus est &#233;gal &#224; celui de sa &lt;a class=&quot;pagelink&quot; href=&quot;Tueur.html#CIBLEETUDIEE&quot; title=&quot;Le tueur&quot;&gt;cible &#233;tudi&#233;e&lt;/a&gt; pour un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Tueur.html&quot; title=&quot;Le tueur&quot;&gt;tueur&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gant-De-Fauconnier.html&quot; title=&quot;Gant de fauconnier&quot;&gt;Gant de fauconnier&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet d’effectuer une manœuvre de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#DESARMEMENT&quot; title=&quot;Les manœuvres offensives&quot;&gt;d&#233;sarmement&lt;/a&gt; ou de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#SUBTILISATION&quot; title=&quot;Les manœuvres offensives&quot;&gt;subtilisation&lt;/a&gt; sur une cible &#224; 9 m ou moins (au choix, &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Bmo.html&quot; title=&quot;BMO&quot;&gt;BMO&lt;/a&gt; de +16) sans provoquer d’&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#ATTAQUEDOPPORTUNITE&quot; title=&quot;Valeurs de combat&quot;&gt;attaque d’opportunit&#233;&lt;/a&gt;. L’objet affect&#233; par la manœuvre est ramen&#233; au porteur si la main gant&#233;e est libre.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-De-Blocage-Des-Sorts.html&quot; title=&quot;Gants de blocage des sorts&quot;&gt;Gants de blocage des sorts&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionnent comme des &lt;a class=&quot;pagelink&quot; href=&quot;Gants-Antiprojectiles.html&quot; title=&quot;Gants antiprojectiles&quot;&gt;gants antiprojectiles&lt;/a&gt;, mais permettent aussi de capturer des projectiles ciblant des alli&#233;s adjacent au porteur. Au prix d&#39;une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, peut d&#233;penser une utlisation journali&#232;re des gants pour bloquer un sort &#224; la place (comme avec l&#39;aptitude de voie du protecteur &lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Protecteur-Mythique.html#BLOCAGEDESORT&quot; title=&quot;Aptitudes de voie du protecteur mythique&quot;&gt;blocage de sort&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-De-D&#233;samor&#231;age-Des-Glyphes.html&quot; title=&quot;Gants de d&#233;samor&#231;age des glyphes&quot;&gt;Gants de d&#233;samor&#231;age des glyphes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Sabotage.html&quot; title=&quot;Sabotage&quot;&gt;Sabotage&lt;/a&gt; pour d&#233;samorcer les pi&#232;ges magiques. Une fois par jour, si un tel test d&#233;passe le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de 10, permettent de changer la condition de d&#233;clenchement du pi&#232;ge cibl&#233;.&lt;/td&gt;&lt;td&gt;9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-In&#233;luctables.html&quot; title=&quot;Gants in&#233;luctables&quot;&gt;Gants in&#233;luctables&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de comp&#233;tence de +4 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Lutte.html&quot; title=&quot;lutte&quot;&gt;lutte&lt;/a&gt;. Au prix d&#39;une utlisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, peut forcer une cr&#233;ature b&#233;n&#233;ficiant d&#39;une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Libert&#233;-De-Mouvement.html&quot; title=&quot;Libert&#233; de mouvement&quot;&gt;libert&#233; de mouvement&lt;/a&gt;&lt;/i&gt; &#224; quand m&#234;me faire un test afin de s&#39;&#233;chapper de l&#39;&#233;treinte du porteur. Au prix de deux utilisations de pouvoir mythique, peut contrer un effet de t&#233;l&#233;portation non-mythique visant &#224; s&#39;&#233;chapper de l&#39;&#233;treinte du porteur.&lt;/td&gt;&lt;td&gt;9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gant-De-Rangement.html&quot; title=&quot;Gant de rangement&quot;&gt;Gant de rangement&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de faire dispara&#238;tre un objet de 10 kg ou moins (rendant son poids n&#233;gligeable) pour le faire r&#233;appara&#238;tre plus tard, &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-Des-Poings-De-Pierre.html&quot; title=&quot;Gants des poings de pierre&quot;&gt;Gants des poings de pierre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Les attaques &#224; mains nues du porteur sont consid&#233;r&#233;es comme d&#39;une cat&#233;gorie de taille sup&#233;rieure et ignorent les &lt;a class=&quot;pagelink&quot; href=&quot;Exploration#Solidite.html&quot; title=&quot;solidit&#233;&quot;&gt;solidit&#233;s&lt;/a&gt; de 8 ou moins. Conf&#232;rent un bonus &#233;gal &#224; son &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Grade.html&quot; title=&quot;Grade&quot;&gt;grade mythique&lt;/a&gt; aux tentatives de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Destruction.html&quot; title=&quot;destruction&quot;&gt;destruction&lt;/a&gt; du porteur.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-De-Fa&#231;onnage.html&quot; title=&quot;Gants de fa&#231;onnage&quot;&gt;Gants de fa&#231;onnage&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permettent de fa&#231;onner ou d’endommager des objets avec une solidit&#233; de 8 ou moins (fa&#231;onnages pr&#233;cis n&#233;cessitants des tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt;) &#224; volont&#233;. Les objets avec une solidit&#233; sup&#233;rieure &#224; 8 sont consid&#233;r&#233;s avec leur solidit&#233; divis&#233;e par 2.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-De-Violence-Soudaine.html&quot; title=&quot;Gants de violence soudaine&quot;&gt;Gants de violence soudaine&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;UI&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Accorde le don &lt;a class=&quot;pagelink&quot; href=&quot;Surprise.html&quot; title=&quot;Surprise&quot;&gt;Surprise&lt;/a&gt; au porteur.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;experts&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;UI&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Accorde &#233;galement le don &lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;trise-Des-Armes-Improvis&#233;es.html&quot; title=&quot;Ma&#238;trise des armes improvis&#233;es&quot;&gt;Ma&#238;trise des armes improvis&#233;es&lt;/a&gt; au porteur.&lt;/td&gt;&lt;td&gt;| 30 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mitaines-D&#233;lasticit&#233;.html&quot; title=&quot;Mitaines d’&#233;lasticit&#233;&quot;&gt;Mitaines d’&#233;lasticit&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus d’alt&#233;ration de +5 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; pour &#233;viter les d&#233;g&#226;ts de &lt;a class=&quot;pagelink&quot; href=&quot;Dangers-Naturels.html#CHUTE&quot; title=&quot;Les dangers naturels&quot;&gt;chute&lt;/a&gt;. Jusqu’&#224; 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par jour, augmentent l’allonge du porteur d’1,50 m, et infligent un malus de -2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDATTAQUE&quot; title=&quot;Valeurs de combat&quot;&gt;jets d’attaque&lt;/a&gt; (-4 pour les armes &#224; deux mains).&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gantelet-De-Rouille.html&quot; title=&quot;Gantelet de rouille&quot;&gt;Gantelet de rouille&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Immunise l’&#233;quipement du porteur contre les attaques d’&lt;a class=&quot;pagelink&quot; href=&quot;Oxydeur.html&quot; title=&quot;Oxydeur&quot;&gt;oxydeur&lt;/a&gt; et la corrosion (magique ou non). Une fois par jour, permettent de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rouille.html&quot; title=&quot;Rouille&quot;&gt;rouille&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;11 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; &lt;a class=&quot;pagelink&quot; href=&quot;Gantelet-De-Rouille-Sup&#233;rieur.html&quot; title=&quot;Gantelet de rouille sup&#233;rieur&quot;&gt;Gantelet de rouille sup&#233;rieur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme un &lt;i&gt;Gantelet de Rouille&lt;/i&gt;, mais permettent de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rouille.html&quot; title=&quot;Rouille&quot;&gt;rouille&lt;/a&gt;&lt;/i&gt; trois fois par jour plut&#244;t qu’une seule.&lt;/td&gt;&lt;td&gt;| 34 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-De-Duelliste.html&quot; title=&quot;Gants de duelliste&quot;&gt;Gants de duelliste&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +4 au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; contre les manœuvres de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#DESARMEMENT&quot; title=&quot;Les manœuvres offensives&quot;&gt;d&#233;sarmement&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#DESTRUCTION&quot; title=&quot;Les manœuvres offensives&quot;&gt;destruction&lt;/a&gt; d’armes, ainsi qu’aux effets cens&#233;s lui faire l&#226;cher son arme au porteur (comme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Graisse.html&quot; title=&quot;Graisse&quot;&gt;graisse&lt;/a&gt;&lt;/i&gt; ou les &#233;tats &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Paniqu&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;paniqu&#233;&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#&#201;tourdi&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;&#233;tourdi&lt;/a&gt;). Si le porteur poss&#232;de la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#ENTRAINEMENTAUXARMES&quot; title=&quot;Le guerrier&quot;&gt;entra&#238;nement aux armes&lt;/a&gt; son bonus d’entra&#238;nement augmente de +2.&lt;/td&gt;&lt;td&gt;15 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gantelets-Du-Briseur-De-Cr&#226;nes.html&quot; title=&quot;Gantelets du briseur de cr&#226;nes&quot;&gt;Gantelets du briseur de cr&#226;nes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaires &#224; des &lt;a class=&quot;pagelink&quot; href=&quot;Gantelet-(Arme).html&quot; title=&quot;Gantelet&quot;&gt;gantelets&lt;/a&gt; +1. Une fois par jour, permet d’effectuer une attaque par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt; qui inflige 4d6 points de d&#233;g&#226;ts et qui peut rendre la cible &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Inconscient.html&quot; title=&quot;Inconscient&quot;&gt;inconsciente&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Chancelant.html&quot; title=&quot;Chancelant&quot;&gt;chancelante&lt;/a&gt; jusqu’&#224; la fin de son prochain tour. Un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Lutteur.html&quot; title=&quot;Le lutteur&quot;&gt;lutteur&lt;/a&gt; qui poss&#232;de la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Lutteur.html#KO&quot; title=&quot;Le lutteur&quot;&gt;KO&lt;/a&gt; voit le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; pour r&#233;sister &#224; ses KO augmenter de 2.&lt;/td&gt;&lt;td&gt;15 302 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brassards-Du-Corbeau.html&quot; title=&quot;Brassards du corbeau&quot;&gt;Brassards du corbeau&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CSU&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, peuvent conf&#233;rer les propri&#233;t&#233;s &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Lancer.html&quot; title=&quot;lancer (propri&#233;t&#233;)&quot;&gt;lancer&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Boomerang.html&quot; title=&quot;boomerang (propri&#233;t&#233;)&quot;&gt;boomerang&lt;/a&gt;&lt;/i&gt; &#224; une arme de corps &#224; corps tenue en main. Une fois par semaine, peuvent devenir des messagers semblables &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Statuette-Merveilleuse.html&quot; title=&quot;Statuette merveilleuse&quot;&gt;statuette merveilleuse de corbeau d&#39;argent&lt;/a&gt; except&#233; qu&#39;ils se t&#233;l&#233;portent au porteur une fois le message d&#233;livr&#233; (ou 24 heures &#233;coul&#233;es).&lt;/td&gt;&lt;td&gt;16 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-Vampiriques.html&quot; title=&quot;Gants vampiriques&quot;&gt;Gants vampiriques&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, permettent de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Baiser-Du-Vampire.html&quot; title=&quot;Baiser du vampire&quot;&gt;baiser du vampire&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Saignement.html&quot; title=&quot;Saignement&quot;&gt;saignement&lt;/a&gt;&lt;/i&gt;. Le sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Baiser-Du-Vampire.html&quot; title=&quot;Baiser du vampire&quot;&gt;baiser du vampire&lt;/a&gt;&lt;/i&gt; peut &#234;tre utilis&#233; &#224; distance (9 m ou moins) si la cible est mourante ou subit un saignement.&lt;/td&gt;&lt;td&gt;18 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gantelets-De-Poigne-Colossale.html&quot; title=&quot;Gantelets de poigne colossale&quot;&gt;Gantelets de poigne colossale&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu’&#224; 20 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par jour, permettent de tenter une manœuvre de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#BOUSCULADE&quot; title=&quot;Les manœuvres offensives&quot;&gt;bousculade&lt;/a&gt; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; sur une attaque &#224; mains nues ou naturelle r&#233;ussie.&lt;/td&gt;&lt;td&gt;20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-Daction-&#192;-Distance.html&quot; title=&quot;Gants d&amp;#39;action &#224; distance&quot;&gt;Gants d’action &#224; distance&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permettent de d&#233;placer des objets ne pensant pas plus de 10kg &#224; 9m ou moins du porteur. Au prix d&#39;une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, permet de porter des attaques &#224; mains nues et d&#39;effectuer certaines manoeuvres offensives &#224; 9m de distance (comme s&#39;il avait une allonge de 9m).&lt;/td&gt;&lt;td&gt;20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-De-Raccourcis.html&quot; title=&quot;Gants de raccourcis&quot;&gt;Gants de raccourcis&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permettent de se lier &#224; une case pendant 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;. Le porteur est consid&#233;r&#233; aussi bien sur sa case que sur la case li&#233;e, bien qu’il ne puisse pas prendre en tenaille, attaquer &#224; distance, lutter, ou effectuer des attaques qui le forcent &#224; se d&#233;placer depuis cette derni&#232;re.&lt;/td&gt;&lt;td&gt;27 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gants-Dinvocateur-Autoritaire.html&quot; title=&quot;Gants d’invocateur autoritaire&quot;&gt;Gants d’invocateur autoritaire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Les cr&#233;atures qu’il convoque comprennent le porteur. Trois fois par jour, permettent de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contr&#244;le-Des-Cr&#233;atures-Convoqu&#233;es.html&quot; title=&quot;Contr&#244;le des cr&#233;atures convoqu&#233;es&quot;&gt;contr&#244;le des cr&#233;atures convoqu&#233;es&lt;/a&gt;&lt;/i&gt; sur une cr&#233;ature convoqu&#233;e &#224; 15 m ou moins.&lt;/td&gt;&lt;td&gt;30 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Serres-De-Leng.html&quot; title=&quot;Serres de Leng&quot;&gt;Serres de Leng&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent 2 attaques de griffe infligeant 1d4 points de d&#233;g&#226;ts chacune qui b&#233;n&#233;ficient d’un bonus d’alt&#233;ration de +3 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDATTAQUE&quot; title=&quot;Valeurs de combat&quot;&gt;jets d’attaque&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt; et qui peuvent rendre la cible &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Confus&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;confuse&lt;/a&gt; en permanence sur un coup critique. Immunise contre les effets de confusion. Infligent un malus de -2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt; tant qu’elles sont port&#233;s.&lt;/td&gt;&lt;td&gt;67 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Diad&#232;me-De-Rubis.html&quot; title=&quot;Diad&#232;me de rubis&quot;&gt;Diad&#232;me de rubis&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaire &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-Dinspiration.html&quot; title=&quot;Bandeau d&amp;#39;inspiration&quot;&gt;bandeau d&#39;inspiration +6&lt;/a&gt;&lt;/i&gt; et &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Serre-T&#234;te-De-Persuasion.html&quot; title=&quot;Serre-t&#234;te de persuasion&quot;&gt;serre-t&#234;te de persuasion&lt;/a&gt;&lt;/i&gt;. Permet au dirigeant l&#233;gitime de la Terre des pharaons de communiquer avec l&#39;agent des seigneurs &#233;l&#233;mentaires du d&#233;sert.&lt;/td&gt;&lt;td&gt;94 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gantelets-De-Ma&#238;tre-Darmes.html&quot; title=&quot;Gantelets de ma&#238;tre d’armes&quot;&gt;Gantelets de ma&#238;tre d’armes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peuvent stocker jusqu’&#224; 10 armes magiquement. Le porteur peut d&#233;gainer les armes stock&#233;es par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;. Trois fois par jour, permettent de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;H&#233;ro&#239;sme-Supr&#234;me.html&quot; title=&quot;H&#233;ro&#239;sme supr&#234;me&quot;&gt;h&#233;ro&#239;sme supr&#234;me&lt;/a&gt;&lt;/i&gt; (porteur uniquement).&lt;/td&gt;&lt;td&gt;110 000 po&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
